def B(id, cat, title, question, rows, unit, ymin, ymax, myth, expl, caveat, source, year, ver="verified", note=None):
    Q.append(dict(id=id, type="bar", category=cat, title=title, question=question, bars=_bars(rows), unit=unit,
                  yRange=[ymin, ymax], myth=myth, explanation=expl, caveat=caveat, source=source,
                  dataYear=year, verification=ver, note=note))

def BB(id, cat, title, question, rows, unit, myth, expl, caveat, source, year, ver="verified", note=None):
    Q.append(dict(id=id, type="bubble", category=cat, title=title, question=question, items=_bars(rows), unit=unit,
                  myth=myth, explanation=expl, caveat=caveat, source=source, dataYear=year, verification=ver, note=note))

def DN(id, cat, title, question, slices, myth, expl, caveat, source, year, ver="verified", note=None):
    P(id, cat, title, question, slices, myth, expl, caveat, source, year, ver, note)
    Q[-1]["type"] = "donut"

def H(id, cat, title, question, bins, myth, expl, caveat, source, year, ver="verified", note=None):
    Q.append(dict(id=id, type="distribution", category=cat, title=title, question=question,
                  bins=[dict(label=l, value=v) for l, v in bins], unit="%", myth=myth, explanation=expl,
                  caveat=caveat, source=source, dataYear=year, verification=ver, note=note))

