P("Q115", C11, "외국인 소유 주택 국적",
  "2025년 말 외국인 소유 주택 10만 8,231가구를 소유자 국적으로 나눠보세요.",
  [("중국", 56.8), ("미국", 21.3), ("캐나다", 6.0), ("대만", 3.1), ("기타", 12.8)],
  "외국인 집주인 문제는 과장된 혐중 프레임이다",
  "외국인 소유 주택의 56.8%가 중국인 소유입니다. 다만 앞 문제처럼 전체 주택의 0.55% 안에서의 비중입니다.",
  "중국 국적에는 동포(조선족)가 상당수이고, 부천·안산 등 6억 원 이하 실거주가 많다는 분석이 있습니다. 미국 국적에는 '검은머리 외국인'(해외 이주 한국계)도 포함됩니다.",
  S_FHOUSE2, 2025, ver="computed", note="중국 56.8%는 보도치, 나머지는 국적별 가구 수(반올림값) ÷ 108,231, 기타 = 나머지")
