   "중국인이 한국 땅을 사들이고 있다",
   "외국인 보유 토지의 절반 이상(53.6%)이 미국인 소유이고, 중국인은 7.9%입니다. 미국인은 '땅', 중국인은 '집'이라는 분석이 나옵니다.",
