  "",
  "70세가 76%로 압도적입니다. 전체 응답자의 64%가 연령 상향에 찬성했습니다(반대 17%).",
  "서울시의원이 공개한 온라인·현장 설문(1,144명)으로 조사기관이 명시되지 않았습니다.",
