  "외국인 노동자는 대부분 최저임금도 안 되는 저임금을 받는다",
  "외국인 임금근로자의 절반(50.2%)이 월 200~300만 원을 받았고, 300만 원 이상도 36.9%였습니다. 200만 원 미만은 12.8%였습니다.",
  "전문인력·영주·재외동포는 300만 원 이상 비중이 높고, 비전문취업(E-9) 노동자는 200~300만 원에 몰려 있습니다. 숙소비 공제, 장시간 노동 등은 임금만으로 드러나지 않습니다.",
