DN("Q267", C10, "치킨집, 5년 버틸 확률",
   "서울에서 문을 연 치킨 전문점을 5년 차까지 살아남은 곳과 그 전에 문 닫은 곳으로 나눠보세요.",
   [("5년 생존", 29.0), ("5년 안에 폐업", 71.0)],
   "치킨집은 망하지 않는 국민 창업 아이템이다",
   "서울시 상권분석 기준 치킨 전문점의 5년 차 생존율은 29.0%였습니다. 점포 수도 2023년 말 6,541곳에서 2025년 말 5,803곳으로 줄었습니다.",
   "전국 치킨 프랜차이즈 가맹점은 2024년 3만 1,397곳으로 오히려 늘어, 개인 점포가 줄고 프랜차이즈로 재편되는 흐름이 함께 나타납니다.",
   src("서울시 상권분석서비스(헤럴드경제 보도)", "https://www.heraldk.com/article/2026033017145641266"), 2025,
   ver="partial", note="5년 생존율 29.0%·점포 수는 보도 확인, 게재 기사 재대조")
DN("Q268", C16, "곡물 자급률",
   "2020년 한국이 소비한 곡물(사료용 포함)을 국내에서 생산한 몫과 수입한 몫으로 나눠보세요.",
   [("국내 생산", 20.2), ("수입", 79.8)],
   "쌀이 남아돌 정도니 한국은 곡물을 거의 자급한다",
   "곡물자급률은 20.2%로 소비하는 곡물의 약 80%를 수입했습니다. 사료용을 뺀 식량자급률도 45.8%였습니다.",
   "쌀은 자급률이 100% 안팎이지만 밀(0.7%)·옥수수(0.8%)·콩(7.7%)은 대부분 수입이라, 품목별로 사정이 크게 다릅니다.",
   src("농림축산식품부 설명자료", "https://mafra.go.kr/bbs/mafra/69/330023/artclView.do"), 2020)
B("Q269", C16, "밥보다 고기",
   "2024년 한국인 1인당 연간 쌀 소비량입니다. 3대 육류(소·돼지·닭) 소비량 막대를 맞춰보세요.",
   [("쌀", 56.4, F_), ("3대 육류", 61.4, T)], "kg", 0, 100,
   "한국인은 여전히 고기보다 쌀을 훨씬 많이 먹는다",
   "2024년 1인당 3대 육류 소비량은 61.4kg으로 쌀(56.4kg)보다 많았습니다. 육류는 2022년 처음 쌀을 앞질렀고 격차가 커지고 있습니다.",
   "쌀은 1984년 130.1kg에서 40년 연속 줄었고, 쌀 소비량은 가공용을 빼고 집계하는 등 기준에 따라 55.8kg으로 발표되기도 합니다. 육류는 뼈 등을 포함한 공급 기준입니다.",
   src("한국농촌경제연구원 자료(헤럴드경제 보도)", "https://www.heraldk.com/article/2026050204400057247"), 2024)
B("Q270", C16, "수입 김치",
   "김치 수입량(거의 전부 중국산)입니다. 2023년을 보고 2024년 막대를 맞춰보세요.",
   [("2023년", 28.7, F_), ("2024년", 31.2, T)], "만 톤", 0, 40,
   "식당에서 나오는 김치는 대부분 국산이다",
   "2024년 김치 수입량은 31만 1,570톤으로 8.7% 늘었고 수입액(1억 8,986만 달러)은 사상 최대였습니다. 수입 김치는 주로 외식업체에서 쓰입니다.",
   "배추값 급등 같은 작황 사정에 따라 수입이 크게 출렁이며, 한국은 김치 수출도 꾸준히 늘려 '수입 김치=국산 김치 몰락'으로만 볼 수는 없습니다.",
   src("관세청 수출입 통계(한국경제 보도)", "https://www.hankyung.com/article/202505205384g"), 2024,
   ver="computed", note="2024년 31만 1,570톤·+8.7%는 보도 확인, 2023년 값은 역산(311,570/1.087) — 게재 기사 재대조")

