  "관광 목적 방문객만 세면 수치가 더 낮고, 중국 단체관광 회복 속도·일본·대만 등 국적 구성 변화에 따라 지역 상권이 받는 효과는 다릅니다.",
  src("한국관광공사 한국관광통계(헤럴드경제 보도)", "https://www.heraldk.com/article/2026012918155213361"), 2025,
