   "개 식용 금지(2027년 2월 7일 시행)를 앞두고 1,537곳 중 1,339곳(87%)이 폐업을 마쳐 계획보다 30% 빨랐습니다. 신고 당시 46만 8천여 마리이던 사육 개는 7천 6백 마리 수준으로 줄었습니다.",
