  "국방부 지표로 2024년 군 내 자살률은 10만 명당 13.3명으로 일반 국민(26.4명)의 절반 수준이었습니다.",
  "군 복무자는 신체검사를 거친 젊은 층이라 연령·건강 구성이 달라 단순 비교에 한계가 있고, 2016년 이후 군 사망사고의 약 69%가 극단적 선택일 만큼 군 사망의 가장 큰 원인이기도 합니다.",
